import{_ as e,o,c as r,a2 as a}from"./chunks/framework.BZO4qERu.js";const g=JSON.parse('{"title":"Настройка канала WeCom (WeWork)","description":"","frontmatter":{},"headers":[],"relativePath":"ru/integrations/channels/wecom.md","filePath":"ru/integrations/channels/wecom.md","lastUpdated":1792323081000}'),n={name:"ru/integrations/channels/wecom.md"};function l(s,t,i,h,d,m){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="настроика-канала-wecom-wework" tabindex="-1">Настройка канала WeCom (WeWork) <a class="header-anchor" href="#настроика-канала-wecom-wework" aria-label="Permalink to &quot;Настройка канала WeCom (WeWork)&quot;">​</a></h1><p>Подключите своего Bot в Memoh к WeCom (企业微信), чтобы он общался с пользователями в рабочем пространстве WeCom вашей организации — в личных сообщениях и групповых чатах.</p><h2 id="предварительные-условия" tabindex="-1">Предварительные условия <a class="header-anchor" href="#предварительные-условия" aria-label="Permalink to &quot;Предварительные условия&quot;">​</a></h2><ul><li>Права администратора в <a href="https://work.weixin.qq.com/" target="_blank" rel="noreferrer">консоли администратора WeCom</a> для создания приложения Bot.</li></ul><h2 id="шаги" tabindex="-1">Шаги <a class="header-anchor" href="#шаги" aria-label="Permalink to &quot;Шаги&quot;">​</a></h2><h3 id="_1-создаите-bot-wecom" tabindex="-1">1. Создайте Bot WeCom <a class="header-anchor" href="#_1-создаите-bot-wecom" aria-label="Permalink to &quot;1. Создайте Bot WeCom&quot;">​</a></h3><p>В консоли администратора WeCom:</p><ol><li>Войдите в <a href="https://work.weixin.qq.com/" target="_blank" rel="noreferrer">консоль администратора WeCom</a>.</li><li>Перейдите в <strong>App Management</strong> &gt; <strong>Custom Apps</strong> или <strong>Bot Management</strong>.</li><li>Создайте новое приложение Bot.</li><li>Запишите учётные данные <strong>Bot ID</strong> и <strong>Secret</strong>.</li></ol><blockquote><p>Официальная документация: <a href="https://developer.work.weixin.qq.com/" target="_blank" rel="noreferrer">WeCom Open Platform</a> · <a href="https://developer.work.weixin.qq.com/document/path/91770" target="_blank" rel="noreferrer">документация WeCom Bot</a></p></blockquote><h3 id="_2-добавьте-канал-в-memoh" tabindex="-1">2. Добавьте канал в Memoh <a class="header-anchor" href="#_2-добавьте-канал-в-memoh" aria-label="Permalink to &quot;2. Добавьте канал в Memoh&quot;">​</a></h3><p>В Memoh:</p><ol><li>Откройте вкладку <strong>Platforms</strong> нужного Bot.</li><li>Нажмите <strong>Add Channel</strong> и выберите <strong>WeCom</strong>.</li><li>Заполните <strong>Bot ID</strong> и <strong>Secret</strong>; собственный <strong>WebSocket URL</strong> указывайте только при необходимости.</li><li>Нажмите <strong>Save and Enable</strong>.</li></ol><p>После включения Memoh подключается к WeCom по WebSocket и начинает получать сообщения.</p><h2 id="учетные-данные" tabindex="-1">Учётные данные <a class="header-anchor" href="#учетные-данные" aria-label="Permalink to &quot;Учётные данные&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Поле</th><th>Обязательное</th><th>Описание</th></tr></thead><tbody><tr><td><strong>Bot ID</strong></td><td>Да</td><td>Идентификатор Bot в WeCom.</td></tr><tr><td><strong>Secret</strong></td><td>Да</td><td>Учётные данные Bot для аутентификации.</td></tr><tr><td><strong>WebSocket URL</strong></td><td>Нет</td><td>Собственная конечная точка WebSocket; если поле пустое, используется точка по умолчанию.</td></tr></tbody></table><h2 id="проверка" tabindex="-1">Проверка <a class="header-anchor" href="#проверка" aria-label="Permalink to &quot;Проверка&quot;">​</a></h2><p>Отправьте Bot <code>/help</code> в личном сообщении или обратитесь к нему в групповом чате через @-упоминание с <code>/help</code>. Bot ответит списком команд — это подтверждает, что канал работает.</p><h2 id="групповые-чаты" tabindex="-1">Групповые чаты <a class="header-anchor" href="#групповые-чаты" aria-label="Permalink to &quot;Групповые чаты&quot;">​</a></h2><p>Bot работает и в групповых чатах WeCom: чтобы получить ответ, упомяните его в группе через @.</p><h2 id="отключение-и-смена-учетных-данных" tabindex="-1">Отключение и смена учётных данных <a class="header-anchor" href="#отключение-и-смена-учетных-данных" aria-label="Permalink to &quot;Отключение и смена учётных данных&quot;">​</a></h2><p>Отключить или удалить канал можно в любой момент на вкладке <strong>Platforms</strong> нужного Bot. Чтобы сменить учётные данные, обновите <strong>Bot ID</strong> / <strong>Secret</strong> в той же панели и сохраните.</p>',21)])])}const p=e(n,[["render",l]]);export{g as __pageData,p as default};
